@using sv_815e4bcde3024c5592068fc2027103a3.Services

<div class="settings-sidebar">
    <h3>Settings</h3>
    <nav>
        @foreach (var section in Sections)
        {
            <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                    @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                @section
            </button>
        }
    </nav>
</div>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_815e4bcde3024c5592068fc2027103a3.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (_profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@_profile.AvatarUrl" alt="Avatar" class="avatar-image" />
                <p class="avatar-url">@_profile.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_bio" @bind:event="oninput"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveChanges">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
        </div>
    }
    else
    {
        <p>Loading profile...</p>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (_profile is null && Profile is not null)
        {
            SetFormFromProfile(Profile);
        }
    }

    private void SetFormFromProfile(UserProfile profile)
    {
        _profile = profile;
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        if (_profile is null) return;
        var updated = _profile with { DisplayName = _displayName, Email = _email, Bio = _bio };
        _profile = updated;
        await OnSave.InvokeAsync(updated);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (Profile is not null)
        {
            SetFormFromProfile(Profile);
        }
    }
}

@using sv_815e4bcde3024c5592068fc2027103a3.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_prefs is not null)
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _channels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@channel.Muted"
                               @onchange="(e) => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                        <span>#@channel.Name</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SavePreferences">Save Preferences</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Preferences saved!</div>
            }
        </div>
    }
    else
    {
        <p>Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = new();
    private bool _showSuccess;

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool Muted { get; set; }
    }

    protected override void OnParametersSet()
    {
        if (_prefs is null && Prefs is not null)
        {
            _prefs = Prefs;
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _channels = Prefs.MutedChannels.Select(c => new ChannelState { Name = c, Muted = true }).ToList();
            // Add some unmuted channels for demo
            if (!_channels.Any(c => c.Name == "help"))
                _channels.Add(new ChannelState { Name = "help", Muted = false });
            if (!_channels.Any(c => c.Name == "watercooler"))
                _channels.Add(new ChannelState { Name = "watercooler", Muted = false });
        }
    }

