@using sv_815e4bcde3024c5592068fc2027103a3.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_prefs is not null)
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in _channels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@channel.Muted"
                               @onchange="(e) => ToggleChannel(channel.Name, (bool)(e.Value ?? false))" />
                        <span>#@channel.Name</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SavePreferences">Save Preferences</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Preferences saved!</div>
            }
        </div>
    }
    else
    {
        <p>Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = new();
    private bool _showSuccess;

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool Muted { get; set; }
    }

    protected override void OnParametersSet()
    {
        if (_prefs is null && Prefs is not null)
        {
            _prefs = Prefs;
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _channels = Prefs.MutedChannels.Select(c => new ChannelState { Name = c, Muted = true }).ToList();
            // Add some unmuted channels for demo
            if (!_channels.Any(c => c.Name == "help"))
                _channels.Add(new ChannelState { Name = "help", Muted = false });
            if (!_channels.Any(c => c.Name == "watercooler"))
                _channels.Add(new ChannelState { Name = "watercooler", Muted = false });
        }
    }

    private void ToggleChannel(string name, bool muted)
    {
        var channel = _channels.FirstOrDefault(c => c.Name == name);
        if (channel is not null)
        {
            channel.Muted = muted;
        }
    }

    private async Task SavePreferences()
    {
        var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        _prefs = updated;
        await OnSave.InvokeAsync(updated);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

