@page "/settings"
@using sv_815e4bcde3024c5592068fc2027103a3.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@_profile" OnSave="SaveProfile" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotifications" />
                break;
            case "Security":
                <SecuritySection Security="@_security"
                                 OnChangePassword="ChangePassword"
                                 OnRevokeSession="RevokeSession" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@_appearance" OnSave="SaveAppearance" />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadCurrentSection();
    }

    private async Task SetActiveSection(string section)
    {
        _activeSection = section;
        await LoadCurrentSection();
    }

    private async Task LoadCurrentSection()
    {
        switch (_activeSection)
        {
            case "Profile":
                _profile ??= await SettingsService.GetProfileAsync();
                break;
            case "Notifications":
                _notificationPrefs ??= await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security":
                _security = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance":
                _appearance ??= await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePassword((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    min-height: 600px;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
    border-right: 1px solid #e0e0e0;
    padding-right: 1rem;
}

.settings-sidebar h3 {
    margin: 0 0 1rem;
    font-size: 1.1rem;
    color: #333;
}

.settings-sidebar nav {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: none;
    background: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    width: 100%;
    transition: background-color 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background-color: #f0f0f0;
    color: #333;
}

.sidebar-item.active {
    background-color: #e3f2fd;
    color: #1565c0;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Settings Content */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.4rem;
    color: #222;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

.settings-section h3 {
    margin: 1.5rem 0 0.75rem;
    font-size: 1.1rem;
    color: #444;
}

/* Form Groups */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 1rem;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

.avatar-url {
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Buttons */
.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background-color: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background-color 0.15s;
}

.btn-primary:hover {
    background-color: #1565c0;
}

.btn-secondary {
    padding: 0.5rem 1.25rem;
    background-color: #f5f5f5;
    color: #555;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background-color 0.15s;
}

.btn-secondary:hover {
    background-color: #e0e0e0;
}

.btn-danger {
    padding: 0.5rem 1.25rem;
    background-color: #d32f2f;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background-color 0.15s;
}

.btn-danger:hover {
    background-color: #b71c1c;
}

.btn-small {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

.toast.success {
    background-color: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Toggle Groups */
.toggle-group {
    margin-bottom: 0.75rem;
}

.toggle-label {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Channel List */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.channel-item {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 0.3rem 0;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border: none;
    background: #fafafa;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    border-radius: 6px;
}

.panel-header:hover {
    background: #f0f0f0;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Security Items */
.security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

.twofa-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.status-indicator {
    font-size: 0.85rem;
    font-weight: 500;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
}

.status-indicator.enabled {
    color: #2e7d32;
    background: #e8f5e9;
}

.status-indicator.disabled {
    color: #c62828;
    background: #ffebee;
}

.last-changed {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #888;
}

.current-session-badge {
    font-size: 0.8rem;
    color: #1976d2;
    font-weight: 500;
}

/* Sessions Table */
.sessions-section {
    margin-top: 1.5rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #eee;
}

.sessions-table th {
    background: #fafafa;
    font-weight: 600;
    color: #555;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.dialog h3 {
    margin: 0 0 0.75rem;
}

.dialog p {
    margin: 0 0 1.25rem;
    color: #555;
    font-size: 0.9rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

/* Error Message */
.error-message {
    color: #d32f2f;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Live Preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.3s;
}

.live-preview h4 {
    margin: 0 0 0.75rem;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #888;
}

.preview-content {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.preview-text {
    margin: 0;
}

.preview-button {
    align-self: flex-start;
    padding: 0.4rem 1rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    background: #f5f5f5;
}

.preview-card {
    padding: 0.75rem;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    background: #fafafa;
}

.preview-card strong {
    display: block;
    margin-bottom: 0.25rem;
}

.preview-card p {
    margin: 0;
    font-size: 0.9em;
    color: #666;
}

/* Theme Preview Variants */
.live-preview.theme-dark {
    background-color: #1e1e1e;
    border-color: #444;
    color: #e0e0e0;
}

.live-preview.theme-dark .preview-button {
    background: #333;
    color: #e0e0e0;
    border-color: #555;
}

.live-preview.theme-dark .preview-card {
    background: #2a2a2a;
    border-color: #444;
}

.live-preview.theme-dark .preview-card p {
    color: #aaa;
}

.live-preview.theme-light {
    background-color: #ffffff;
    border-color: #e0e0e0;
    color: #333;
}

.live-preview.theme-system {
    background-color: #f8f9fa;
    border-color: #dee2e6;
    color: #495057;
}

/* Font Size Preview Variants */
.live-preview.font-small {
    font-size: 0.85rem;
}

.live-preview.font-medium {
    font-size: 1rem;
}

.live-preview.font-large {
    font-size: 1.15rem;
}

/* Compact Mode */
.live-preview.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.live-preview.compact .preview-content {
    gap: 0.4rem;
}

